{"relative_path": "factory/temp/factory/infra/validation.py", "function_name": "_feedback_from_audit", "new_function_code": "def _feedback_from_audit(findings: list[ReviewFinding], audit: AuditResult) -> dict[str, str]:
    """Return {task_id: formatted_block} for blocker findings and high-severity audit risks."""
    out: dict[str, list[str]] = {}
    for tid, blocks in _collect_blocker_findings(findings):
        out.setdefault(tid, []).extend(blocks)
    for blocks in _collect_high_risks(audit):
        for tid, lines in blocks.items():
            out.setdefault(tid, []).extend(lines)
    return {tid: "\n".join(lines) for tid, lines in out.items()}


def _collect_blocker_findings(findings: list[ReviewFinding]) -> Iterator[tuple[str, list[str]]]:
    """Yield (task_id, formatted_lines) for each blocker finding."""
    for f in findings:
        if getattr(f, "severity", None) != "blocker":
            continue
        tid = getattr(f, "task_id", None)
        if not tid:
            continue
        yield tid, _format_finding_lines(f)


def _collect_high_risks(audit: AuditResult) -> Iterator[dict[str, list[str]]]:
    """Yield {task_id: formatted_lines} for each high/critical audit risk."""
    risks = getattr(audit, "risks", None) or []
    for r in risks:
        if getattr(r, "severity", None) not in ("Critical", "High"):
            continue
        yield _format_risk_lines(r)


def _format_finding_lines(f: ReviewFinding) -> list[str]:
    """Format a single blocker finding into display lines."""
    tid = getattr(f, "task_id", None) or "unknown"
    lines = [f"[{tid}] {getattr(f, 'title', '')}"]
    detail = getattr(f, "detail", None)
    if detail:
        lines.append(f"  {detail}")
    return lines


def _format_risk_lines(r: Any) -> dict[str, list[str]]:
    """Format a single high-severity risk into {task_id: lines}."""
    tid = getattr(r, "task_id", None) or "unknown"
    lines = [f"[{tid}] {getattr(r, 'title', '')}"]
    detail = getattr(r, "detail", None)
    if detail:
        lines.append(f"  {detail}")
    return {tid: lines}"}
